+// "0 dependents" and "could not resolve dependents" are different claims, and
+// printing the first when the second is true is the failure the Track 2
+// curveball named.
+func dependentsPhrase(e ChangedEntity) string {
+	switch e.DependentsTier {
+	case Unresolvable:
+		if e.Dependents == 0 {
+			return "dependents unresolvable (graph could not see this region)"
+		}
+		return fmt.Sprintf("%d+ dependents (unresolvable — this is a floor)", e.Dependents)
