package gate

// This file holds the two questions the collect layer has to answer about a
// file or an entity before any signal runs: is this thing code at all, and if
// the graph could not analyse it, could that silence be hiding a caller?
//
// Both live here rather than in the collect layer because both are judgements
// about evidence, and every other judgement about evidence in this package is
// pure and unit-tested. Putting them next to the CGO boundary would make them
// the only rules in Gate that could not be tested in milliseconds.

// proseKinds are entity kinds that describe a document's structure rather than
// code: a Markdown heading, a fenced block, a bullet.
//
// They have to be excluded, and the reason is specific rather than tidiness.
// Gate resolves every changed entity against the graph and reports the ones it
// cannot find as regions the graph could not analyse. A Markdown heading is
// never in the symbol graph, so a change set that touches a design document
// manufactures dozens of "unresolvable" entities — on this repository, 66 of
// 583, nearly all of them headings in Gate's own PLAN.md.
//
// That is not a cosmetic problem. The curveball's whole point is that the
// unresolvable marker means "the graph could not see here, so absence of a
// finding is not evidence of safety". A marker that fires on prose is a marker
// a reader learns to skip, and then it is not there on the day it fires on a
// Ruby template that really is hiding a caller. Precision in what we admit we
// cannot see is part of the claim.
//
// Prose entities are excluded from the change set, never silently: the collect
// layer reports how many were dropped and why.
var proseKinds = map[string]bool{
	"section":    true,
	"heading":    true,
	"code_fence": true,
	"paragraph":  true,
	"list_item":  true,
	"blockquote": true,
	"table":      true,
	"table_row":  true,
	"link":       true,
	"frontmatter": true,
}

// IsProseKind reports whether an entity kind describes prose structure rather
// than code, and so can carry no dependency relations in either direction.
//
// Configuration kinds such as "setting" are deliberately absent: a changed
// setting can genuinely break something, and dropping it would be exactly the
// silent narrowing this package exists to prevent. It stays in the change set
// and is simply reported as having no resolvable dependents, which is true.
func IsProseKind(kind string) bool { return proseKinds[kind] }

// PartitionProse splits a change set into the entities worth analysing and a
// count of the prose entities removed. The count is returned rather than
// discarded so the caller can disclose the narrowing instead of performing it
// quietly.
func PartitionProse(entities []ChangedEntity) (analysable []ChangedEntity, prose int) {
	analysable = make([]ChangedEntity, 0, len(entities))
	for _, e := range entities {
		if IsProseKind(e.Kind) {
			prose++
			continue
		}
		analysable = append(analysable, e)
	}
	return analysable, prose
}

// inertLanguages are languages whose files cannot invoke code at all: prose,
// data, stylesheet and diff formats.
//
// This exists because of what the provider's capability report cannot say. The
// obvious rule — "mark a file as a blind spot when its language supports none
// of the relations the blast-radius walk follows" — was measured against this
// repository and is wrong. Markdown, CSS, Patch, Git Ignore, HTML, Vue and
// Svelte all advertise exactly [CONTAINS, DEFINES], so the capability report
// cannot separate a Vue single-file component, which embeds JavaScript and can
// absolutely hide a caller, from a CHANGELOG that cannot hide anything. The
// missing relation support is not the signal; for the template languages it is
// the symptom.
//
// So the classification is Gate's, and it is written as a denylist on purpose.
// An unrecognised language falls through as capable of hiding a caller, which
// costs one extra line in a report. An allowlist would fail the other way: a
// template language nobody thought of would be silently certified as clean,
// which is the precise failure the Track 2 curveball named. When a rule has to
// guess, it should guess toward disclosure.
var inertLanguages = map[string]bool{
	"Markdown": true, "MDX": true, "reStructuredText": true, "AsciiDoc": true,
	"Org": true, "Plain Text": true, "Text": true, "License": true,

	"JSON": true, "JSON5": true, "JSONC": true, "JSON Lines": true,
	"YAML": true, "TOML": true, "INI": true, "CSV": true, "TSV": true,
	"Properties": true, "Lock": true,

	"CSS": true, "SCSS": true, "Sass": true, "Less": true, "SVG": true,

	"Patch": true, "Diff": true,
	"Git Ignore": true, "Git Attributes": true, "Git Config": true,
}

// CanHideACaller reports whether silence about a file in this language might be
// concealing a dependency, and so is worth reporting as a blind spot.
//
// The empty language is treated as capable: an unclassified file is exactly the
// case where a confident silence is least defensible.
func CanHideACaller(language string) bool { return !inertLanguages[language] }

package gate

import (
	"fmt"
	"sort"
	"strings"
)

// coverageFindingLimit bounds the coverage section. Unchecked entities beyond
// it are still counted in the header and still rank in the review order.
const coverageFindingLimit = 10

// Coverage reports the entities nobody checked.
//
// The collect layer resolves each entity's CoverageState; this decides what is
// worth reporting. Unchecked entities with dependents lead, because "nothing
// tests this and other code depends on it" is a different claim from "nothing
// tests this dead corner".
//
// NoResolver is never reported as a finding. Not being able to look for tests
// is a limit of Gate, not a defect in the change, and charging the author for
// it would be the quiet dishonesty this tool exists to avoid. It surfaces in
// the header count and in Availability instead.
func Coverage(entities []ChangedEntity) []Finding {
	var withDependents, without []Finding
	for _, e := range entities {
		if e.Coverage != Unchecked {
			continue
		}
		finding := Finding{
			Dimension: DimCoverage,
			Subject:   e.Anchor,
			// The tier is stated rather than left at its zero value, and that
			// is the fix for a defect worth recording: an unset tier used to
			// render as "confirmed", so every coverage finding claimed proof it
			// had never been asked for. Unset silently meaning trusted is the
			// same failure the evidence tiers exist to prevent, one layer up.
			//
			// Confirmed is honest here only because ResolveCoverage now demotes
			// an entity in an unresolvable region to NoResolver, which never
			// reaches this loop. What is left is a genuine graph observation:
			// we looked at every incoming edge and none came from a test.
			Tier: coverageTier(e),
			Summary: fmt.Sprintf("%s %s is unchecked: no test covers it (%s)",
				e.Kind, e.ChangeType, e.DependentsCounts.Describe()),
			// An absence claim always ships with the way to settle it, even at
			// Confirmed. Every other finding says "here is what I found, go
			// look"; this one says "I found nothing", and a reader has no way
			// to distinguish a true absence from a test the graph cannot see
			// unless Gate hands them the command.
			Verify: coverageVerifyHint(e),
		}
		if e.Dependents > 0 {
			withDependents = append(withDependents, finding)
		} else {
			without = append(without, finding)
		}
	}

	// Rank inside each group by blast radius before the cap applies. Without
	// this the section is truncated in the entity order, which is alphabetical
	// by path — so a 39-dependent unchecked type in internal/sem could be cut
	// while a 1-dependent helper in internal/cli survived, purely because "c"
	// sorts before "s". The cap decides how much to print; it should not also
	// decide what matters.
	sortByBlastRadius(withDependents)
	sortByBlastRadius(without)

	findings := append(withDependents, without...)
	if len(findings) > coverageFindingLimit {
		findings = findings[:coverageFindingLimit]
	}
	return findings
}

// sortByBlastRadius orders findings most-dependents-first, with path and name
// as tiebreaks so the order is total and two runs agree.
func sortByBlastRadius(findings []Finding) {
	sort.SliceStable(findings, func(i, j int) bool {
		a, b := findings[i], findings[j]
		if a.dependents != b.dependents {
			return a.dependents > b.dependents
		}
		if a.Subject.Path != b.Subject.Path {
			return a.Subject.Path < b.Subject.Path
		}
		return a.Subject.Name < b.Subject.Name
	})
}

// coverageTier says how far the "nobody tested this" claim can be trusted.
//
// An entity whose own region the graph could not analyse never reaches a
// coverage finding — ResolveCoverage marks it NoResolver — so the remaining
// case is a clean region, where the absence of a test edge is a real
// observation. The unresolvable arm is kept anyway: it costs one branch, and
// the alternative is a function that is only correct as long as its caller
// stays correct.
func coverageTier(e ChangedEntity) EvidenceTier {
	if e.DependentsCounts.Region == Unresolvable {
		return Unresolvable
	}
	return Confirmed
}

// coverageVerifyHint is how a reader settles an absence claim for themselves.
func coverageVerifyHint(e ChangedEntity) string {
	if e.VerifyHint != "" {
		return e.VerifyHint
	}
	return fmt.Sprintf("rg -n '\\b%s\\b' -g '*test*'   # a test the graph cannot resolve would not appear above",
		lastSegment(e.Name))
}

// lastSegment reduces a qualified name to the part a text search will match:
// the diff reports methods as "Router.ServeHTTP", and no test file contains
// that string.
func lastSegment(name string) string {
	if i := strings.LastIndex(name, "."); i >= 0 && i+1 < len(name) {
		return name[i+1:]
	}
	return name
}

// testPathMarkers are the path shapes that mean "this file holds tests". The
// list is convention, not proof, and it is the reason CoverageState has a
// NoResolver arm: a language whose tests match none of these is reported as
// unresolvable rather than as untested.
var testPathMarkers = []string{"_test.", "test_", ".test.", ".spec.", "/tests/", "/test/"}

// IsTestPath reports whether a repository-relative path looks like a test file.
func IsTestPath(path string) bool {
	for _, marker := range testPathMarkers {
		if strings.Contains(path, marker) {
			return true
		}
	}
	return strings.HasPrefix(path, "test/") || strings.HasPrefix(path, "tests/")
}

// ResolveCoverage decides, for each entity, whether a test exercises it.
//
// Coverage is read off the graph rather than by running a search per entity:
// an incoming dependency edge from a symbol that lives in a test file is direct
// evidence that a test reaches this code, and the edges are already loaded. A
// per-entity search would be more thorough and would cost seconds each, which
// on an agent-sized change set is minutes.
//
// hasTests says whether the repository contains any test files at all. When it
// does not, every entity is NoResolver rather than Unchecked: "this repo has no
// test tree we can read" is not the same claim as "this change is untested",
// and Gate must not convert one into the other.
func ResolveCoverage(entities []ChangedEntity, ix *Index, hasTests bool) {
	for i := range entities {
		entity := &entities[i]
		if !hasTests {
			entity.Coverage = NoResolver
			continue
		}
		// A region the graph could not analyse cannot be searched for tests
		// either. The edges that would prove a test reaches this code are the
		// same edges the parser failed to produce, so reporting Unchecked here
		// would charge the author for Gate's blind spot — the coverage-side
		// twin of the dependent count that was reported as a confident zero.
		if _, partial := ix.PartialReason(entity.Path); partial {
			entity.Coverage = NoResolver
			continue
		}
		ids := ix.Resolve(entity.Name, entity.Path)
		if len(ids) == 0 {
			// The diff named an entity the graph does not know — an
			// unsupported language, or a file that failed to parse. Absence of
			// a symbol is absence of evidence, not evidence of absence.
			entity.Coverage = NoResolver
			continue
		}
		entity.Coverage = Unchecked
		for _, test := range ix.Dependents(ids, 1) {
			if IsTestPath(test.Path) {
				entity.Coverage = Verified
				entity.CoveringTests = append(entity.CoveringTests, test.Name)
			}
		}
		sort.Strings(entity.CoveringTests)
	}
}

