// findingMarker is the sigil in front of a finding's subject. It delegates to
// the tier's own marker and adds one the tier type does not have: an unset
// tier is marked, because an unmarked line reads as confirmed and that is the
// one thing an unset tier must not read as.
func findingMarker(t EvidenceTier) string {
	switch t {
	case Confirmed, Heuristic, Unresolvable:
		return t.Marker()
	}
	return "!"
}

